const coreCSS=document.createElement('style');coreCSS.textContent='.blankLayout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:20px}.blankLayout canvas{width:100%;background:#080b10;touch-action:none}.blankLayout aside{max-height:68vh;overflow:auto;padding:0 10px}.blankDialog label{display:block;margin:10px 0}.blankDialog input:not([type=color]):not([type=checkbox]),.blankDialog select,.blankDialog textarea{width:100%;background:#1b1f27;color:#eee;border:1px solid #414754;padding:8px;border-radius:5px}.blankDialog textarea{min-height:80px;resize:vertical}.blankLayer{display:flex;gap:6px;padding:10px 0;border-bottom:1px solid #30343e}.blankLayer.selected{background:#bba0f415}.blankLayer button:first-child{flex:1;text-align:left}.blankAdd{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.blankAdd select{width:auto}.blankEmpty{padding:30px;color:#9ca1ad;border:1px dashed #444}.blankDialog .studioActions label{flex:1}#blankTime{flex:1}@media(max-width:850px){.blankLayout{grid-template-columns:1fr}.blankLayout aside{max-height:none}.blankLayer{flex-wrap:wrap}}';document.head.append(coreCSS);

blankDialog.querySelector('#blankSeekTime').oninput=e=>{blankPlaying=false;blankAge=Math.max(0,Math.min(blank.duration,+e.target.value));paintBlank()};

function openLayerTools(layer,panel){blankPlaying=false;playing=false;const originalFX=fx,originalSave=saveEffects;fx={...structuredClone(fx),...structuredClone(layer.params)};saveEffects=function(){layer.params=structuredClone(fx);base._renderKey='';saveBlank()};const restore=()=>{if(chessEditing)setChessMode(false);layer.params=structuredClone(fx);if(['chess','city','noir','battle','depot'].includes(panel))layer.duration=fx[panel+'Duration'];blank.duration=Math.max(blank.duration,layer.start+layer.duration);blankDialog.querySelector('#blankDuration').value=blank.duration;blankDialog.querySelector('#blankTime').max=blank.duration;renderBlankLayers();for(const key of ['userAssets','assetReplacements','cutoutMasks'])if(fx[key])originalFX[key]=structuredClone(fx[key]);fx=originalFX;saveEffects=originalSave;localStorage.setItem('motion-effects',JSON.stringify(fx));syncDuration();base._renderKey='';saveBlank();renderBlankInspector()};editor.addEventListener('close',restore,{once:true});openEditor();playing=false;selectEffect(panel,false);const d=phaseTimes(),times={tears:7.5,zoom:d.tear,light:d.lamp,fire:d.fire,people:d.people,outdoor:d.outdoor,blur:d.outdoor,camera:d.parallax,finish:d.red,chess:d.chess,city:d.city,noir:d.noir,battle:d.battle,depot:d.depot};t=(times[panel]||0)/settings.duration;document.querySelector('#play').textContent='▶'}

let blankSnapshots=[];try{blankSnapshots=JSON.parse(localStorage.getItem('motion-blank-snapshots')||'[]')}catch{}
function archiveBlank(){blankSnapshots.push({savedAt:new Date().toISOString(),composition:structuredClone(blank)});localStorage.setItem('motion-blank-snapshots',JSON.stringify(blankSnapshots))}
function refreshBlankSnapshots(){const select=blankDialog.querySelector('#blankSnapshots');select.innerHTML='<option value="">Saved snapshots…</option>';blankSnapshots.forEach((item,i)=>{const o=document.createElement('option');o.value=i;o.textContent=item.composition.name+' · '+new Date(item.savedAt).toLocaleString();select.append(o)})}
blankDialog.querySelector('#newBlank').onclick=()=>{archiveBlank();blank={version:1,name:'Untitled composition',width:960,height:540,duration:20,background:'#080b10',layers:[],context:{transcript:'',intent:'',metaphor:'',soundPlan:''}};blankSelected=null;blankAge=0;blankDialog.close();openBlank();saveBlank()};blankDialog.querySelector('#blankSnapshots').onchange=e=>{if(e.target.value==='')return;const snapshot=structuredClone(blankSnapshots[+e.target.value].composition);archiveBlank();blank=snapshot;blankSelected=null;blankAge=0;blankDialog.close();openBlank();saveBlank()};

